<?php
namespace App\Services;
use App\Models\{DiagnosticFinding,EvidenceFile,EvidenceRelationship,Investigation};
class DiagnosticEngine {
 public function run(Investigation $i): void { $i->findings()->delete(); EvidenceRelationship::where('investigation_id',$i->id)->delete(); $required=[];$hosting=[];$phpLogs=[];$db=[];$vite=[];$http=[];$keyIssues=[];$composer=[];$storage=[];$docroot=[];$docrootBad=[];$jsErrors=[];$jsStack=[];$forbidden=[];$missing404=[];
 foreach($i->evidence as $e){$text=(string)($e->content ?? '');$facts=[];$cat=$e->category;if(preg_match('/"php"\s*:\s*"?([^",}\s]+)/i',$text,$m)){$required[$e->id]=$m[1];$facts['required_php']=$m[1];}if(preg_match('/PHP(?: Version)?\s*[:=]?\s*(\d+\.\d+(?:\.\d+)?)/i',$text,$m)){$hosting[$e->id]=$m[1];$facts['visible_php']=$m[1];}if(preg_match('/requires php|PHP Fatal error/i',$text))$phpLogs[]=$e->id;if(preg_match('/SQLSTATE|Access denied for user|could not find driver/i',$text,$m))$db[$e->id]=$m[0];if(preg_match('/manifest\.json|failed to load module script|Vite manifest not found|assets\/.*404/i',$text,$m))$vite[$e->id]=$m[0];if(preg_match('/\b(500|403|404)\b/',$text,$m))$http[$e->id]=$m[1];
 if(preg_match('/No application encryption key has been specified/i',$text)){$keyIssues[$e->id]='application log reports a missing encryption key';}
 if($cat==='project'&&preg_match('/^\s*APP_KEY\s*=\s*(.*)\s*$/mi',$text,$m)){$v=trim(trim($m[1]),'"\'');if($v===''||strtolower($v)==='null'){$keyIssues[$e->id]='environment file contains an empty APP_KEY';}else{$facts['app_key']='present';}}
 if(preg_match('/^(.*(?:requirements could not be resolved|Conclusion:[^\n]*|can only install one of[^\n]*|requires php[^\n]*)).*$/mi',$text,$m)){$composer[$e->id]=trim(substr($m[1],0,200));$facts['composer_conflict']=trim(substr($m[1],0,200));}
 if(preg_match('/[^\n]*(?:storage\/(?:logs|framework)|bootstrap\/cache)[^\n]*(?:Permission denied|failed to open stream)[^\n]*|[^\n]*Permission denied[^\n]*(?:storage|bootstrap\/cache)[^\n]*/i',$text,$m)){$storage[$e->id]=trim(substr($m[0],0,200));$facts['permission_error']=trim(substr($m[0],0,200));}
 if($cat==='hosting'&&preg_match('/document\s*root\s*[:=]?\s*(\S+)/i',$text,$m)){$root=rtrim($m[1],'/\\');$facts['visible_docroot']=$root;$docroot[$e->id]=$root;$base=strtolower(basename(str_replace('\\','/',$root)));if($base!==''&&$base!=='public')$docrootBad[$e->id]=$root;}
 if($cat==='browser'&&preg_match('/((?:Uncaught\s+)?(?:TypeError|ReferenceError|SyntaxError|Error|Exception)[^\n]{0,160})/i',$text,$m)){$jsErrors[$e->id]=trim($m[1]);$facts['js_error']=trim(substr($m[1],0,160));}
 if($cat==='browser'&&preg_match('/at\s+https?:\/\/\S+/i',$text)){$jsStack[$e->id]='stack trace present';}
 if(preg_match('/\b403\b/',$text))$forbidden[$e->id]='HTTP 403';
 if(preg_match('/\b404\b/',$text))$missing404[$e->id]='HTTP 404';
 $e->update(['extracted'=>$facts,'state'=>'extracted']);}
 foreach($required as $rid=>$need)foreach($hosting as $hid=>$got)if((float)preg_replace('/[^0-9.]/','',$need)>(float)$got)$this->finding($i,'PHP_VERSION_MISMATCH','PHP compatibility','critical','Hosting PHP version is below project requirement',"composer.json requires $need while hosting evidence shows $got.",'PHP '.$need.' or newer','PHP '.$got,array_unique([$rid,$hid,...$phpLogs,...array_keys($http)]),'Strongly supported by direct project and hosting observations.');
 if($db)$this->finding($i,'DATABASE_CONNECTION_FAILURE','Configuration','high','Database connection failure observed','Application evidence contains: '.reset($db),'Reachable database with matching credentials','Connection error',array_keys($db),'Verified log observation; exact cause needs further evidence.');
 if($vite)$this->finding($i,'VITE_ASSET_FAILURE','Frontend assets','high','Vite production asset failure observed','Evidence contains: '.reset($vite),'Built assets and matching manifest','Missing manifest or failed asset',array_unique([...array_keys($vite),...array_keys($http)]),'Strongly supported by explicit browser/deployment evidence.');
 if($keyIssues)$this->finding($i,'MISSING_APP_KEY','Configuration','high','Laravel encryption key is missing','Evidence reports: '.reset($keyIssues).'. The key value itself is never displayed.','Configured APP_KEY in the deployment environment','Missing or empty APP_KEY',array_keys($keyIssues),'Confirmed by explicit log or environment-file observation; no key material is exposed.');
 if($composer)$this->finding($i,'COMPOSER_PLATFORM_CONFLICT','Dependencies','high','Composer platform requirement conflict','Dependency evidence contains: '.reset($composer),'Resolvable dependency set for the project platform','Conflicting package requirement',array_keys($composer),'Verified package-manager output; resolution needs the full conflict text.');
 if($storage)$this->finding($i,'STORAGE_PERMISSION_FAILURE','Configuration','high','Storage or cache directory is not writable','Evidence contains: '.reset($storage),'Writable storage/ and bootstrap/cache/ directories','Permission denied on write',array_keys($storage),'Verified filesystem error; fix requires host access, which DeploySift never performs.');
 if($docrootBad)$this->finding($i,'DOCUMENT_ROOT_MISMATCH','Hosting','high','Hosting document root does not point at Laravel public/','Hosting evidence shows document root: '.reset($docrootBad).'. Treat panel wording as observed text, not a verified server setting.','Document root ending in the Laravel public/ directory','Document root ending elsewhere',array_keys($docrootBad),'Strongly supported when the panel text names the path explicitly; otherwise treat as inferred.');
 if($jsErrors)$this->finding($i,'BROWSER_JS_EXCEPTION','Browser','medium','Browser JavaScript exception observed','Console evidence contains: '.reset($jsErrors),'Error-free console during the failing flow','Uncaught exception',array_unique([...array_keys($jsErrors),...array_keys($jsStack),...array_keys($missing404)]),'Verified console text; stack frames and failing requests strengthen the link when present.');
 if($forbidden)$this->finding($i,'HTTP_ASSET_FORBIDDEN','Frontend assets','medium','Server refuses an asset request (HTTP 403)','Evidence records HTTP 403 responses.','Publicly reachable assets with correct permissions','HTTP 403 on resource',array_unique([...array_keys($forbidden),...array_keys($hosting)]),'Verified status code; exact blocked path needs the request log.');
 if($missing404&&! $vite)$this->finding($i,'HTTP_ASSET_MISSING','Frontend assets','medium','Referenced asset is missing (HTTP 404)','Evidence records HTTP 404 responses with asset references.','All referenced assets present in build output','HTTP 404 on asset',array_unique([...array_keys($missing404),...array_keys($jsErrors)]),'Verified status code; compare the manifest and asset references to confirm.');
 foreach($i->findings as $f) EvidenceRelationship::create(['investigation_id'=>$i->id,'finding_id'=>$f->id,'relationship'=>'supports','evidence_ids'=>$f->evidence_ids,'detail'=>'Evidence linked by deterministic rule: '.$f->title]); $i->update(['status'=>'completed']); }
 private function finding(Investigation $i,string $id,string $cat,string $sev,string $title,string $detail,string $expected,string $observed,array $evidence,string $confidence):void{DiagnosticFinding::create(['investigation_id'=>$i->id,'identifier'=>$id,'category'=>$cat,'severity'=>$sev,'title'=>$title,'detail'=>$detail,'expected'=>$expected,'observed'=>$observed,'confidence'=>$confidence,'evidence_ids'=>$evidence,'rule_name'=>$id]);}
}
